---Update on LogAction
UPDATE L
SET L.ActionNameEN = LG.ActionNameEN, L.ActionNameCH = LG.ActionNameCH, L.ActionNameCS = LG.ActionNameCS, L.ActionNameJP = LG.ActionNameJP, L.ActionNameIT= LG.ActionNameIT, L.ActionNameTH=LG.ActionNameTH, L.ActionNameKO=LG.ActionNameKO, L.ActionNameVI = LG.ActionNameVI, L.ActionNameCN = LG.ActionNameCN
FROM LogAction L WITH (ROWLOCK,UPDLOCK)
	INNER JOIN #Log LG WITH (NOLOCK) ON L.ActionID = LG.ActionID

DROP TABLE #Log